// Generates docs/cli-reference.md from the help data in src/help.ts.
//
//   bun scripts/gen-cli-reference.ts --write   write docs/cli-reference.md
//   bun scripts/gen-cli-reference.ts --check   exit 1 if the committed file differs from a fresh render
//   bun scripts/gen-cli-reference.ts --path <file>   use another file (tests)
import { readFileSync, writeFileSync } from "node:fs";
import { COMMANDS, ENV, OPTIONS } from "../src/help";

export function render(): string {
  return [
    "# CLI reference",
    "",
    "Generated by `bun scripts/gen-cli-reference.ts --write` from `src/help.ts`. Do not edit by hand.",
    "",
    "## Commands",
    "",
    ...COMMANDS.flatMap((c) => [`### ${c.name}`, "", "```", `factory ${c.usage}`, "```", "", `${c.does}.`, ""]),
    "## Options",
    "",
    ...OPTIONS.map(([k, v]) => `- \`${k}\`: ${v}`),
    "",
    "## Environment",
    "",
    ...ENV.map(([k, v]) => `- \`${k}\`: ${v}`),
    "",
  ].join("\n");
}

if (import.meta.main) {
  const args = process.argv.slice(2);
  const at = args.indexOf("--path");
  const path = at >= 0 ? args[at + 1]! : new URL("../docs/cli-reference.md", import.meta.url).pathname;
  if (args.includes("--write")) writeFileSync(path, render());
  else if (args.includes("--check")) {
    let have = "";
    try {
      have = readFileSync(path, "utf8");
    } catch {}
    if (have !== render()) {
      console.error(`${path} is stale: run bun scripts/gen-cli-reference.ts --write`);
      process.exit(1);
    }
  } else process.stdout.write(render());
}
